const records = $input.all().map(i => i.json);
if (!records.length || !records[0].id) {
  return []; // nothing due - stay silent
}
const today = new Date().toISOString().slice(0, 10);
const lines = records.map(r => {
  const f = r.fields || r;
  const due = (f['Next follow-up'] || '').slice(0, 10);
  const flag = due < today ? ':red_circle: OVERDUE' : ':large_yellow_circle: today';
  const note = f.Notes ? ` - _${String(f.Notes).slice(0, 80)}_` : '';
  return `- ${flag} *${f.Name || 'Unnamed'}*${f.Company ? ` (${f.Company})` : ''}${note}`;
});
return [{ json: { message: `:telephone_receiver: *Follow-ups due (${lines.length})*\n${lines.join('\n')}` } }];
